From 4548728981de259d7d37d0ae968a777b09794168 Mon Sep 17 00:00:00 2001
From: Dan Carpenter <dan.carpenter@oracle.com>
Date: Thu, 31 Jul 2014 15:57:51 +0300
Subject: [PATCH] ASoC: pxa: pxa-ssp: small leak in probe()

There is a small memory leak if probe() fails.

Fixes: 2023c90c3a2c ('ASoC: pxa: pxa-ssp: add DT bindings')
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Mark Brown <broonie@linaro.org>

diff --git a/sound/soc/pxa/pxa-ssp.c b/sound/soc/pxa/pxa-ssp.c
index 199a8b377553..0109f6c2334e 100644
--- a/sound/soc/pxa/pxa-ssp.c
+++ b/sound/soc/pxa/pxa-ssp.c
@@ -723,7 +723,8 @@ static int pxa_ssp_probe(struct snd_soc_dai *dai)
 		ssp_handle = of_parse_phandle(dev->of_node, "port", 0);
 		if (!ssp_handle) {
 			dev_err(dev, "unable to get 'port' phandle\n");
-			return -ENODEV;
+			ret = -ENODEV;
+			goto err_priv;
 		}

 		priv->ssp = pxa_ssp_request_of(ssp_handle, "SoC audio");
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug is caused by a failure to properly handle resource cleanup when the `pxa_ssp_probe` function encounters an error while trying to obtain the `ssp_handle`. Specifically, if the `of_parse_phandle` function fails and returns `NULL`, the original code immediately returns an error code without releasing any previously allocated resources, leading to a memory leak.

        Commit message:
        ASoC: pxa: pxa-ssp: small leak in probe()

There is a small memory leak if probe() fails.

Fixes: 2023c90c3a2c ('ASoC: pxa: pxa-ssp: add DT bindings')
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Mark Brown <broonie@linaro.org>  

        Patch:

 static int pxa_ssp_probe(struct snd_soc_dai *dai)
 {
 	struct device *dev = dai->dev;
 	struct ssp_priv *priv;
 	int ret;

 	priv = kzalloc(sizeof(struct ssp_priv), GFP_KERNEL);
 	if (!priv)
 		return -ENOMEM;

 	if (dev->of_node) {
 		struct device_node *ssp_handle;

 		ssp_handle = of_parse_phandle(dev->of_node, "port", 0);
 		if (!ssp_handle) {
 			dev_err(dev, "unable to get 'port' phandle\n");
-			return -ENODEV;
+			ret = -ENODEV;
+			goto err_priv;
 		}

 		priv->ssp = pxa_ssp_request_of(ssp_handle, "SoC audio");
 		if (priv->ssp == NULL) {
 			ret = -ENODEV;
 			goto err_priv;
 		}
 	} else {
 		priv->ssp = pxa_ssp_request(dai->id + 1, "SoC audio");
 		if (priv->ssp == NULL) {
 			ret = -ENODEV;
 			goto err_priv;
 		}
 	}

 	priv->dai_fmt = (unsigned int) -1;
 	snd_soc_dai_set_drvdata(dai, priv);

 	return 0;

 err_priv:
 	kfree(priv);
 	return ret;
 }



        Provide a response strictly in the following format:
        Code statements:
        <text1>
        <text2>
        ...
        <textN>

Code statements:
```c
ssp_handle = of_parse_phandle(dev->of_node, "port", 0);
if (!ssp_handle) {
    dev_err(dev, "unable to get 'port' phandle\n");
    return -ENODEV;
}
```

